using System.Reflection;using TownOfHost;using TownOfHost.Modules.MainMenu;using UnityEngine;using Obj=UnityEngine.Object;
partial class Program {
 static Transform OnlineNativePath(MainMenuManager menu){var p=menu.transform;foreach(string name in "MainUI/AspectScaler/RightPanel/MaskedBlackScreen/OnlineButtons/AspectSize/Scaler".Split('/')){var next=p.Find(name);if(next==null){var g=new GameObject(name);g.transform.SetParent(p,false);next=g.transform;}p=next;}return p;}
 static (MainMenuManager menu,SeasideMainMenuPatch.HomeView view,PassiveButton create,PassiveButton code) OnlineFixture(){
  var x=Setup();BindHome(x);var scaler=OnlineNativePath(x.menu);
  var c=new TownOfHost.Templates.SimpleButton(scaler,"Create Lobby Button",new(),Color.white,Color.white,()=>{},"",false).Button;
  var j=new TownOfHost.Templates.SimpleButton(scaler,"Enter Code Button",new(),Color.white,Color.white,()=>{},"",false).Button;
  c.gameObject.SetActive(true);j.gameObject.SetActive(true);x.view.Hide();x.menu.Home=false;Check(x.view.TryOpenOnlinePage());return(x.menu,x.view,c,j);
 }
 static string OnlineAssetFolder(){var root=Path.Combine(AppContext.BaseDirectory,"online-fixture-"+Guid.NewGuid().ToString("N"));BepInEx.Paths.ConfigPath=root;var p=Path.Combine(root,"TOH-Shell","MainMenu","Online");Directory.CreateDirectory(p);return p;}
 static void OnlineAsset(string folder,string file,int w,int h){var bytes=new byte[32];bytes[0]=137;bytes[1]=80;bytes[2]=78;bytes[3]=71;System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(bytes.AsSpan(16,4),(uint)w);System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(bytes.AsSpan(20,4),(uint)h);File.WriteAllBytes(Path.Combine(folder,file),bytes);}
 static void OnlinePageTests(){
  var config=BepInEx.Paths.ConfigPath;OnlineAssetFolder();
  Test("online page is only presented after known native online adapters exist",()=>{var x=Setup();BindHome(x);Check(!x.view.TryOpenOnlinePage()&&!x.view.OnlinePage);x.view.Dispose();});
  Test("inactive native online screen does not bypass native access checks",()=>{var x=OnlineFixture();x.view.Hide();OnlineNativePath(x.menu).gameObject.SetActive(false);Check(!x.view.TryOpenOnlinePage());x.view.Dispose();});
  Test("online native postfix opens the custom page after normal flow",()=>{var x=OnlineFixture();x.view.Hide();x.menu.Home=false;Call("OnlineMenuReady",x.menu);Check(x.view.Visible&&x.view.OnlinePage);x.view.Dispose();});
  Test("online page hides all home and mode choice hit areas",()=>{var x=OnlineFixture();Check(x.view.Visible);foreach(var id in SeasideMenuLayout.Targets.Select(t=>t.Id).Concat(SeasidePlayLayout.Ids))Check(!Proxy(id).gameObject.activeSelf);Check(SeasideOnlineLayout.Ids.All(id=>Proxy(id).gameObject.activeSelf));x.view.Dispose();});
  Test("online card labels and heading have their own renderers",()=>{var x=OnlineFixture();Check(Text("OnlineHeadingText").text=="オンライン"&&Text("OnlineCreateText").text=="ゲーム作成"&&Text("OnlineCodeText").text=="コードを入力"&&Text("OnlineBackText").text=="戻る");x.view.Dispose();});
  Test("empty images retain independent disabled renderers and full card colliders",()=>{var x=OnlineFixture();foreach(string id in new[]{"OnlineCreate","OnlineCode"}){var art=Obj.Objects.Single(g=>g.name==id+"Artwork");Check(!art.GetComponent<SpriteRenderer>().enabled&&art.GetComponentsInChildren<Collider2D>(true).Length==0);var poly=Proxy(id).GetComponent<PolygonCollider2D>();Check(poly.enabled&&poly.points.Length==8);Near(poly.points.Max(p=>p.x)-poly.points.Min(p=>p.x),SeasideOnlineLayout.Rect(id).Width/100);}x.view.Dispose();});
  foreach(string id in new[]{"OnlineCreate","OnlineCode"})Test("standard event invoked once after press: "+id,()=>{var x=OnlineFixture();var native=id=="OnlineCreate"?x.create:x.code;Proxy(id).OnClick.Invoke();Check(native.OnClick.Calls==0);Pump(x.view);Check(native.OnClick.Calls==1&&!x.view.Visible);x.view.Dispose();});
  foreach(string id in new[]{"OnlineCreate","OnlineCode"})Test("rapid repeated clicks keep one native action: "+id,()=>{var x=OnlineFixture();var native=id=="OnlineCreate"?x.create:x.code;for(int i=0;i<25;i++)Proxy(id).OnClick.Invoke();Pump(x.view);Check(native.OnClick.Calls==1);x.view.Dispose();});
  foreach(string id in new[]{"OnlineCreate","OnlineCode"})Test("native-disabled action remains disabled: "+id,()=>{var x=OnlineFixture();var native=id=="OnlineCreate"?x.create:x.code;native.enabled=false;Proxy(id).OnClick.Invoke();Pump(x.view);Check(native.OnClick.Calls==0&&x.view.Visible);x.view.Dispose();});
  Test("native-hidden code action is never exposed by the proxy",()=>{var x=OnlineFixture();x.view.Hide();x.code.gameObject.SetActive(false);Check(x.view.TryOpenOnlinePage());Proxy("OnlineCode").OnClick.Invoke();Pump(x.view);Check(x.code.OnClick.Calls==0);x.view.Dispose();});
  Test("online hover and press share existing button motion",()=>{var x=OnlineFixture();Proxy("OnlineCreate").OnMouseOver.Invoke();Pump(x.view,15);Check(Math.Abs(Motion("OnlineCreate").localRotation.Z)>.01);Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view,6);Near(Motion("OnlineCreate").localScale.y,.95);Near(Motion("OnlineCreate").localRotation.Z,0);x.view.Dispose();});
  Test("controller focus selects online artwork without moving its collider",()=>{var x=OnlineFixture();Controller.currentTouchType=Controller.TouchType.Joystick;ControllerManager.Instance.CurrentUiState.CurrentSelection=Proxy("OnlineCode");var pos=Proxy("OnlineCode").transform.localPosition;Pump(x.view,15);Check(Math.Abs(Motion("OnlineCode").localRotation.Z)>.01);Near(Proxy("OnlineCode").transform.localPosition.x,pos.x);x.view.Dispose();});
  foreach(bool disabled in new[]{false,true})Test("online back restores title, wave disabled="+disabled,()=>{var x=OnlineFixture();TownOfHost.Main.DisableWaveAnimation.Value=disabled;Proxy("OnlineBack").OnClick.Invoke();Pump(x.view,170);Check(x.view.Page==SeasidePage.Home&&!x.view.OnlinePage&&Proxy("Play").gameObject.activeSelf&&!Proxy("OnlineCreate").gameObject.activeSelf);x.view.Dispose();});
  Test("online ESC follows the same back path",()=>{var x=OnlineFixture();Input.Escape=true;Pump(x.view,1);Input.Escape=false;Pump(x.view,170);Check(!x.view.OnlinePage&&x.view.Page==SeasidePage.Home);x.view.Dispose();});
  Test("native host/code return adapter restores online cards",()=>{var x=OnlineFixture();Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view);Check(x.view.ResumeNativePlay());Check(x.view.OnlinePage&&Proxy("OnlineCode").gameObject.activeSelf);x.view.Dispose();});
  Test("failed native action restores usable online menu",()=>{var x=OnlineFixture();x.create.OnClick.AddListener((Action)(()=>throw new Exception("synthetic")));Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view);Check(x.view.Visible&&x.view.OnlinePage);x.view.Dispose();});
  Test("native reset clears the custom page",()=>{var x=OnlineFixture();Call("Reset",x.menu);Check(!x.view.OnlinePage&&x.view.Page==SeasidePage.Home);x.view.Dispose();});
  Test("foreign gameplay scene never builds online UI",()=>{var x=OnlineFixture();GameScene();Call("OnlineMenuReady",x.menu);Check(!(bool)Call("MenuSceneAvailable",x.menu));x.view.Dispose();});
  Test("repeated online opening reuses controls and original positions",()=>{var x=OnlineFixture();var count=Obj.Objects.Count(g=>g.name.StartsWith("Seaside_Online"));var p=Proxy("OnlineCode").transform.localPosition;for(int i=0;i<20;i++){x.view.Hide();x.menu.Home=false;Check(x.view.TryOpenOnlinePage());}Check(count==3&&Obj.Objects.Count(g=>g.name.StartsWith("Seaside_Online"))==3);Near(Proxy("OnlineCode").transform.localPosition.x,p.x);x.view.Dispose();});
  Test("native reset animation retains Shell cover but blocks early input",()=>{var x=OnlineFixture();x.menu.Home=false;x.menu.animating=true;Pump(x.view,3);Check(x.view.Visible);Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view);Check(x.create.OnClick.Calls==0);x.menu.Home=true;x.menu.animating=false;Pump(x.view);Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view);Check(x.create.OnClick.Calls==1);x.view.Dispose();});
  Test("online controls and placeholders are removed on dispose",()=>{var x=OnlineFixture();x.view.Dispose();Check(!Obj.Objects.Any(g=>g.name=="SeasideOnlineArtwork"||g.name=="Seaside_OnlineCreate"));});
  foreach(var size in new[]{(1920,1080),(1024,768),(1280,1024),(3440,1440),(800,1280)})Test("online safe layout and pointer mapping "+size,()=>{var f=SeasideMenuLayout.Fit(size.Item1,size.Item2);foreach(string id in SeasideOnlineLayout.Ids){var r=SeasideOnlineLayout.Rect(id);Check(r.X>=0&&r.Y>=0&&r.X+r.Width<=1672&&r.Y+r.Height<=941);var p=f.ToScreen(r.CenterX,r.CenterY);var a=f.ToArt(p.x,p.y);Near(a.x,r.CenterX);Near(a.y,r.CenterY);}});
  foreach(string id in new[]{"OnlineCreate","OnlineCode"})foreach(var size in new[]{(1000d,750d),(600d,1200d),(2000d,500d)})Test("cover crop fits without changing the hit box "+id+size,()=>{var r=SeasideOnlineLayout.Crop(id,size.Item1,size.Item2);var box=SeasideOnlineLayout.ImageBox(id);Near(r.Width/r.Height,box.Width/box.Height);Check(r.X>=0&&r.Y>=0&&r.X+r.Width<=size.Item1+.001&&r.Y+r.Height<=size.Item2+.001);});
  Test("zoom and offset stay inside image bounds",()=>{var r=SeasideOnlineLayout.Crop("OnlineCreate",1000,750,3,1,-1);Near(r.Y,0);Near(r.X+r.Width,1000);});
  Test("invalid crop dimensions rejected",()=>{foreach(var n in new[]{0d,-1d,double.NaN,double.PositiveInfinity}){bool bad=false;try{SeasideOnlineLayout.Crop("OnlineCreate",n,750);}catch(ArgumentOutOfRangeException){bad=true;}Check(bad);}});
  Test("nonfinite crop options use safe defaults",()=>{var r=SeasideOnlineLayout.Crop("OnlineCreate",1000,750,double.NaN,double.NaN,double.PositiveInfinity);Check(double.IsFinite(r.X)&&double.IsFinite(r.Width));});
  Test("corrupt artwork leaves a usable blank card",()=>{var folder=OnlineAssetFolder();File.WriteAllText(Path.Combine(folder,"create.png"),"not an image");var x=OnlineFixture();Check(!Obj.Objects.Single(g=>g.name=="OnlineCreateArtwork").GetComponent<SpriteRenderer>().enabled);Proxy("OnlineCreate").OnClick.Invoke();Pump(x.view);Check(x.create.OnClick.Calls==1);x.view.Dispose();});
  Test("oversized PNG dimensions rejected before decoder",()=>{var folder=OnlineAssetFolder();OnlineAsset(folder,"create.png",9000,9000);ImageConversion.Success=true;var x=OnlineFixture();Check(!Obj.Objects.Single(g=>g.name=="OnlineCreateArtwork").GetComponent<SpriteRenderer>().enabled);x.view.Dispose();ImageConversion.Success=false;});
  Test("separate artwork files and JSON crop options preserve click geometry",()=>{var folder=OnlineAssetFolder();OnlineAsset(folder,"create.png",1000,750);OnlineAsset(folder,"join.png",600,1200);File.WriteAllText(Path.Combine(folder,"create.json"),"{\"Zoom\":2,\"OffsetX\":1,\"OffsetY\":-1}");ImageConversion.Success=true;var x=OnlineFixture();foreach(string id in new[]{"OnlineCreate","OnlineCode"}){var r=Obj.Objects.Single(g=>g.name==id+"Artwork").GetComponent<SpriteRenderer>();Check(r.enabled);Near(r.transform.localScale.x,r.transform.localScale.y);Check(Proxy(id).GetComponent<PolygonCollider2D>().points.Length==8);}var crop=SeasideOnlineLayout.Crop("OnlineCreate",1000,750,2,1,-1);Near(Obj.Objects.Single(g=>g.name=="OnlineCreateArtwork").GetComponent<SpriteRenderer>().sprite.rect.width,crop.Width);x.view.Dispose();ImageConversion.Success=false;});
  Test("malformed image config falls back to centered cover",()=>{var folder=OnlineAssetFolder();OnlineAsset(folder,"create.png",1000,750);File.WriteAllText(Path.Combine(folder,"create.json"),"broken");ImageConversion.Success=true;var x=OnlineFixture();var r=Obj.Objects.Single(g=>g.name=="OnlineCreateArtwork").GetComponent<SpriteRenderer>();Check(r.enabled);Near(r.sprite.rect.width,SeasideOnlineLayout.Crop("OnlineCreate",1000,750).Width);x.view.Dispose();ImageConversion.Success=false;});
  Test("friends and dynamic version remain on the custom online page",()=>{OnlineAssetFolder();var x=OnlineFixture();TownOfHost.Main.PluginShowVersion="2.2.2";Pump(x.view,1);Check(Text("ShellVersion").text=="TOH-Shell v2.2.2"&&Proxy("Friends").gameObject.activeInHierarchy);x.view.Dispose();TownOfHost.Main.PluginShowVersion="2.2.0β";});
  BepInEx.Paths.ConfigPath=config;ImageConversion.Success=false;
 }
}
